blocks.code:
h1 {
  color: #2563eb;
  font-family: system-ui, sans-serif;
}

.lead {
  font-size: 20px;
  font-weight: 600;
  color: #0f172a;
}

p {
  color: #475569;
  line-height: 1.6;
}

.box {
  background: #dbeafe;
  border: 3px solid #2563eb;
  padding: 16px;      /* воздух внутри */
  margin: 12px;       /* отступ снаружи */
  width: 200px;
}

.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  background: #f1f5f9;
  padding: 12px;
}

.item {
  background: #2563eb;
  color: #fff;
  padding: 18px 26px;
  border-radius: 8px;
  font-family: system-ui, sans-serif;
}

tasks.tests:
equal(style('h1', 'color'), 'rgb(255, 0, 0)', 'Цвет заголовка');
equal(style($$('p')[0], 'font-size'), '20px', 'Размер шрифта абзаца');
equal(style($$('p')[1], 'font-size'), '20px', 'Размер шрифта у всех абзацев');

var c = $('.card');
assert(c, 'Не найден элемент с классом card');
equal(style(c, 'padding-top'), '16px', 'Внутренний отступ');
equal(style(c, 'border-top-width'), '2px', 'Толщина рамки');
equal(style(c, 'border-top-style'), 'solid', 'Стиль рамки');
equal(style(c, 'border-top-color'), 'rgb(0, 0, 255)', 'Цвет рамки');
equal(style(c, 'border-top-left-radius'), '8px', 'Скругление');
equal(style(c, 'box-sizing'), 'border-box', 'box-sizing');

var h = $('.header');
assert(h, 'Не найден .header');
equal(style(h, 'display'), 'flex', 'display');
equal(style(h, 'justify-content'), 'space-between', 'justify-content');
equal(style(h, 'align-items'), 'center', 'align-items');
assert(style(h, 'gap').indexOf('10px') === 0, 'gap должен быть 10px, а сейчас: ' + style(h, 'gap'));

var b = $('.btn');
assert(b, 'Не найден .btn');
equal(style(b, 'color'), 'rgb(255, 255, 255)', 'Цвет текста');
equal(style(b, 'background-color'), 'rgb(37, 99, 235)', 'Цвет фона');
equal(style(b, 'padding-top'), '12px', 'Отступы');
equal(style(b, 'border-top-left-radius'), '6px', 'Скругление');
equal(style(b, 'cursor'), 'pointer', 'Курсор');
